const { itemTypeName, getState } = options
const state = getState();
const isMultiSelect = state.grid.selectedRows.length > 1;
if (isMultiSelect) {
	return {
		hidden: true
	};
}
const rowId = state.grid.selectedRows[0];
const disabled = ArasModules.item.isNew(itemTypeName, rowId);

return { disabled, hidden: false };
